exercises.fix_solution:
def weighted_base_by_wave(spark: SparkSession, cfg: RunConfig) -> DataFrame:
    """Weighted base per wave from the configured silver table."""
    silver = spark.table(cfg.silver_table)
    scope = spark.table(cfg.scope_table)
    in_scope = silver.join(scope, "region").filter(F.col("in_scope"))
    return in_scope.groupBy("wave_id").agg(F.sum("final_weight").alias("weighted_base"))
